<?php
/**
 * Outage post type, editor, front-end shortcodes, banner and public REST API.
 *
 * @package FinetTroubleshoot
 */

declare( strict_types=1 );

namespace FinetTroubleshoot\Outages;

final class OutageModule {
	public const POST_TYPE = 'wpfinet_outage'; public const TAX_PROVIDER = 'wpfinet_provider'; public const TAX_SERVICE = 'wpfinet_service'; public const TAX_AREA = 'wpfinet_area';
	public const META_TYPE = '_wpfinet_incident_type'; public const META_STATUS = '_wpfinet_outage_status'; public const META_START = '_wpfinet_incident_start'; public const META_ESTIMATED_END = '_wpfinet_estimated_end'; public const META_ACTUAL_END = '_wpfinet_actual_end'; public const META_PRIORITY = '_wpfinet_priority'; public const META_BANNER = '_wpfinet_banner'; public const META_TIMELINE = '_wpfinet_timeline'; public const META_AREA_NOTE = '_wpfinet_area_note'; public const META_INTERNAL_NOTE = '_wpfinet_internal_note';
	public function register_hooks(): void {
		add_action( 'init', array( $this, 'register' ) ); add_action( 'add_meta_boxes_' . self::POST_TYPE, array( $this, 'boxes' ) ); add_action( 'save_post_' . self::POST_TYPE, array( $this, 'save' ), 10, 2 );
		add_filter( 'post_type_link', array( $this, 'permalink' ), 10, 2 ); add_filter( 'rewrite_rules_array', array( $this, 'rewrite_rules' ) );
		add_action( 'wp_enqueue_scripts', array( $this, 'assets' ) ); add_shortcode( 'wpfinet_outages', array( $this, 'shortcode' ) ); add_shortcode( 'wpfinet_outage_status', array( $this, 'status_shortcode' ) );
		add_filter( 'the_content', array( $this, 'single_content' ) ); add_action( 'wp_body_open', array( $this, 'banner' ) ); add_action( 'wp_footer', array( $this, 'banner_fallback' ) );
		add_action( 'save_post_' . self::POST_TYPE, array( $this, 'flush' ), 20 ); add_action( 'deleted_post', array( $this, 'flush' ) ); add_action( 'rest_api_init', array( $this, 'routes' ) );
	}
	public function register(): void {
		register_post_type( self::POST_TYPE, array( 'labels' => array( 'name' => __( 'Driftstörningar', 'finet-troubleshoot' ), 'singular_name' => __( 'Driftstörning', 'finet-troubleshoot' ), 'add_new_item' => __( 'Ny driftstörning', 'finet-troubleshoot' ), 'edit_item' => __( 'Redigera driftstörning', 'finet-troubleshoot' ) ), 'public' => true, 'show_ui' => true, 'show_in_menu' => false, 'show_in_rest' => true, 'supports' => array( 'title', 'editor', 'excerpt', 'revisions', 'author' ), 'has_archive' => 'driftstorningar', 'rewrite' => array( 'slug' => 'driftstorningar', 'with_front' => false ), 'menu_icon' => 'dashicons-warning', 'map_meta_cap' => true ) );
		foreach ( array( self::TAX_PROVIDER => __( 'Tjänsteleverantörer', 'finet-troubleshoot' ), self::TAX_SERVICE => __( 'Berörda tjänster', 'finet-troubleshoot' ), self::TAX_AREA => __( 'Berörda områden', 'finet-troubleshoot' ) ) as $taxonomy => $label ) { register_taxonomy( $taxonomy, self::POST_TYPE, array( 'labels' => array( 'name' => $label, 'singular_name' => $label ), 'show_ui' => true, 'show_in_rest' => true, 'hierarchical' => true, 'rewrite' => false ) ); }
		if ( '2.0.1' !== get_option( 'wpfinet_outage_rewrite_version' ) ) { flush_rewrite_rules( false ); update_option( 'wpfinet_outage_rewrite_version', '2.0.1', false ); }
	}
	public function boxes(): void { add_meta_box( 'wpfinet-outage-details', __( 'Driftinformation', 'finet-troubleshoot' ), array( $this, 'box_details' ), self::POST_TYPE, 'normal', 'high' ); add_meta_box( 'wpfinet-outage-updates', __( 'Statusuppdateringar', 'finet-troubleshoot' ), array( $this, 'box_updates' ), self::POST_TYPE, 'normal', 'default' ); }
	public function box_details( \WP_Post $post ): void {
		wp_nonce_field( 'wpfinet_outage_save', 'wpfinet_outage_nonce' ); $get = static fn ( string $key, string $default = '' ): string => (string) get_post_meta( $post->ID, $key, true ) ?: $default;
		?>
		<div class="wpfinet-outage-fields"><p><label><?php esc_html_e( 'Typ', 'finet-troubleshoot' ); ?><select name="wpfinet_incident_type"><option value="acute" <?php selected( $get( self::META_TYPE, 'acute' ), 'acute' ); ?>><?php esc_html_e( 'Akut driftstörning', 'finet-troubleshoot' ); ?></option><option value="planned" <?php selected( $get( self::META_TYPE ), 'planned' ); ?>><?php esc_html_e( 'Planerat arbete', 'finet-troubleshoot' ); ?></option></select></label> <label><?php esc_html_e( 'Status', 'finet-troubleshoot' ); ?><select name="wpfinet_outage_status"><?php foreach ( $this->statuses() as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $get( self::META_STATUS, 'investigating' ), $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label> <label><?php esc_html_e( 'Prioritet', 'finet-troubleshoot' ); ?><select name="wpfinet_priority"><?php foreach ( array( 'low' => __( 'Låg', 'finet-troubleshoot' ), 'normal' => __( 'Normal', 'finet-troubleshoot' ), 'high' => __( 'Hög', 'finet-troubleshoot' ), 'critical' => __( 'Kritisk', 'finet-troubleshoot' ) ) as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $get( self::META_PRIORITY, 'normal' ), $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label></p><p><label><?php esc_html_e( 'Start (sajtens tidszon)', 'finet-troubleshoot' ); ?><input type="datetime-local" name="wpfinet_incident_start" value="<?php echo esc_attr( $this->input_time( $get( self::META_START ) ) ); ?>"></label> <label><?php esc_html_e( 'Beräknat slut', 'finet-troubleshoot' ); ?><input type="datetime-local" name="wpfinet_estimated_end" value="<?php echo esc_attr( $this->input_time( $get( self::META_ESTIMATED_END ) ) ); ?>"></label> <label><?php esc_html_e( 'Faktiskt slut', 'finet-troubleshoot' ); ?><input type="datetime-local" name="wpfinet_actual_end" value="<?php echo esc_attr( $this->input_time( $get( self::META_ACTUAL_END ) ) ); ?>"></label></p><p><label><input type="checkbox" name="wpfinet_banner" value="1" <?php checked( '1', $get( self::META_BANNER ) ); ?>> <?php esc_html_e( 'Visa i global driftbanner', 'finet-troubleshoot' ); ?></label></p><p><label><?php esc_html_e( 'Extra information om område (visas publikt, även i REST-API och export)', 'finet-troubleshoot' ); ?><input class="large-text" name="wpfinet_area_note" value="<?php echo esc_attr( $get( self::META_AREA_NOTE ) ); ?>"></label></p><p><label><?php esc_html_e( 'Intern anteckning (visas aldrig publikt)', 'finet-troubleshoot' ); ?><textarea class="large-text" rows="3" name="wpfinet_internal_note"><?php echo esc_textarea( $get( self::META_INTERNAL_NOTE ) ); ?></textarea></label></p></div>
		<?php
	}
	public function box_updates( \WP_Post $post ): void {
		$timeline = get_post_meta( $post->ID, self::META_TIMELINE, true ); $timeline = is_array( $timeline ) ? $timeline : array(); usort( $timeline, static fn ( array $a, array $b ): int => strcmp( (string) ( $b['time'] ?? '' ), (string) ( $a['time'] ?? '' ) ) );
		?>
		<div class="wpfinet-outage-updates"><p><label><?php esc_html_e( 'Status', 'finet-troubleshoot' ); ?><select name="wpfinet_update_status"><?php $current_status = (string) get_post_meta( $post->ID, self::META_STATUS, true ) ?: 'investigating'; foreach ( $this->statuses() as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $current_status, $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label></p><p><label><?php esc_html_e( 'Meddelande', 'finet-troubleshoot' ); ?><textarea class="large-text" rows="3" name="wpfinet_update_text"></textarea></label></p><p><label><input type="checkbox" name="wpfinet_update_public" value="1" checked> <?php esc_html_e( 'Visa publikt', 'finet-troubleshoot' ); ?></label></p><p><em><?php esc_html_e( 'Uppdateringen läggs till när driftstörningen uppdateras.', 'finet-troubleshoot' ); ?></em></p><?php if ( $timeline ) : ?><ul><?php foreach ( $timeline as $item ) : ?><li><strong><?php echo esc_html( $this->status_label( (string) ( $item['status'] ?? '' ) ) ); ?></strong> · <?php echo esc_html( $this->format_time( (string) ( $item['time'] ?? '' ) ) ); ?><br><?php echo esc_html( (string) ( $item['text'] ?? '' ) ); ?></li><?php endforeach; ?></ul><?php endif; ?></div>
		<?php
	}
	public function save( int $post_id, \WP_Post $post ): void {
		if ( ! isset( $_POST['wpfinet_outage_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['wpfinet_outage_nonce'] ) ), 'wpfinet_outage_save' ) || ! current_user_can( 'edit_post', $post_id ) || wp_is_post_revision( $post_id ) ) { return; }
		$type = sanitize_key( wp_unslash( $_POST['wpfinet_incident_type'] ?? 'acute' ) ); $status = sanitize_key( wp_unslash( $_POST['wpfinet_outage_status'] ?? 'investigating' ) ); $priority = sanitize_key( wp_unslash( $_POST['wpfinet_priority'] ?? 'normal' ) );
		update_post_meta( $post_id, self::META_TYPE, in_array( $type, array( 'acute', 'planned' ), true ) ? $type : 'acute' ); update_post_meta( $post_id, self::META_STATUS, array_key_exists( $status, $this->statuses() ) ? $status : 'investigating' ); update_post_meta( $post_id, self::META_PRIORITY, in_array( $priority, array( 'low', 'normal', 'high', 'critical' ), true ) ? $priority : 'normal' );
		foreach ( array( 'wpfinet_incident_start' => self::META_START, 'wpfinet_estimated_end' => self::META_ESTIMATED_END, 'wpfinet_actual_end' => self::META_ACTUAL_END ) as $field => $meta ) { update_post_meta( $post_id, $meta, $this->save_time( sanitize_text_field( wp_unslash( $_POST[ $field ] ?? '' ) ) ) ); }
		update_post_meta( $post_id, self::META_BANNER, ! empty( $_POST['wpfinet_banner'] ) ? '1' : '0' ); update_post_meta( $post_id, self::META_AREA_NOTE, sanitize_text_field( wp_unslash( $_POST['wpfinet_area_note'] ?? '' ) ) ); update_post_meta( $post_id, self::META_INTERNAL_NOTE, sanitize_textarea_field( wp_unslash( $_POST['wpfinet_internal_note'] ?? '' ) ) );
		$text = sanitize_textarea_field( wp_unslash( $_POST['wpfinet_update_text'] ?? '' ) ); if ( $text ) { $timeline = get_post_meta( $post_id, self::META_TIMELINE, true ); $timeline = is_array( $timeline ) ? $timeline : array(); $update_status = sanitize_key( wp_unslash( $_POST['wpfinet_update_status'] ?? $status ) ); $update_status = array_key_exists( $update_status, $this->statuses() ) ? $update_status : $status; $timeline[] = array( 'time' => current_time( 'mysql' ), 'text' => $text, 'status' => array_key_exists( $update_status, $this->statuses() ) ? $update_status : $status, 'author' => get_current_user_id(), 'public' => ! empty( $_POST['wpfinet_update_public'] ) ); update_post_meta( $post_id, self::META_TIMELINE, $timeline ); update_post_meta( $post_id, self::META_STATUS, $update_status ); }
	}
	/** @return array<string,string> */ public function statuses(): array { return array( 'scheduled' => __( 'Planerad', 'finet-troubleshoot' ), 'investigating' => __( 'Undersöks', 'finet-troubleshoot' ), 'identified' => __( 'Identifierad', 'finet-troubleshoot' ), 'in_progress' => __( 'Åtgärd pågår', 'finet-troubleshoot' ), 'monitoring' => __( 'Övervakning', 'finet-troubleshoot' ), 'resolved' => __( 'Löst', 'finet-troubleshoot' ), 'cancelled' => __( 'Inställd', 'finet-troubleshoot' ) ); }
	public function status_label( string $status ): string { return $this->statuses()[ $status ] ?? $status; }
	public function permalink( string $url, \WP_Post $post ): string { if ( self::POST_TYPE !== $post->post_type ) { return $url; } return home_url( user_trailingslashit( 'driftstorningar/' . mysql2date( 'Y/m/d', $post->post_date ) . '/' . $post->post_name ) ); }
	/** @return array<string,string> */ public function rewrite_rules( array $rules ): array { return array( '^driftstorningar/([0-9]{4})/([0-9]{2})/([0-9]{2})/([^/]+)/?$' => 'index.php?post_type=' . self::POST_TYPE . '&name=$matches[4]' ) + $rules; }
	public function assets(): void { wp_register_style( 'wpfinet-outages', FINET_TS_URL . 'assets/build/outages.css', array(), FINET_TS_VERSION ); wp_register_script( 'wpfinet-outages', FINET_TS_URL . 'assets/build/outages.js', array(), FINET_TS_VERSION, true ); }
	public function shortcode( array $attributes ): string { $atts = shortcode_atts( array( 'status' => 'all', 'service' => '', 'provider' => '', 'area' => '', 'limit' => 10, 'filters' => 'false' ), $attributes, 'wpfinet_outages' ); $filters = array_filter( array( 'service' => sanitize_title( $atts['service'] ), 'provider' => sanitize_title( $atts['provider'] ), 'area' => sanitize_title( $atts['area'] ) ) ); $buckets = 'all' === $atts['status'] ? array( 'current', 'upcoming', 'past' ) : array( in_array( $atts['status'], array( 'current', 'upcoming', 'past' ), true ) ? $atts['status'] : 'current' ); $this->enqueue_assets(); ob_start(); echo '<section class="wpfinet-outages" data-wpfinet-outages>'; foreach ( $buckets as $bucket ) { $this->render_bucket( $bucket, $filters, absint( $atts['limit'] ) ?: 10 ); } echo '</section>'; return (string) ob_get_clean(); }
	public function status_shortcode(): string { $outages = ( new OutageRepository() )->find( 'current', array(), 100 ); /* 2.0.1 used a limit of 2, so the count never exceeded 2 (B4). */ $url = esc_url( home_url( '/driftstorningar/' ) ); return $outages ? '<a class="wpfinet-outage-status is-affected" href="' . $url . '">⚠ ' . esc_html( sprintf( _n( '%d aktuell driftstörning', '%d aktuella driftstörningar', count( $outages ), 'finet-troubleshoot' ), count( $outages ) ) ) . '</a>' : '<a class="wpfinet-outage-status is-clear" href="' . $url . '">✓ ' . esc_html__( 'Inga kända driftstörningar', 'finet-troubleshoot' ) . '</a>'; }
	public function render_bucket( string $bucket, array $filters, int $limit ): void { $labels = array( 'current' => __( 'Nuvarande driftstörningar', 'finet-troubleshoot' ), 'upcoming' => __( 'Kommande driftstörningar', 'finet-troubleshoot' ), 'past' => __( 'Tidigare driftstörningar', 'finet-troubleshoot' ) ); $outages = ( new OutageRepository() )->find( $bucket, $filters, $limit ); echo '<section class="wpfinet-outages__section"><h2>' . esc_html( $labels[ $bucket ] ) . '</h2>'; if ( ! $outages ) { echo '<p class="wpfinet-outages__empty">' . esc_html( 'current' === $bucket ? __( 'Inga aktuella driftstörningar.', 'finet-troubleshoot' ) : ( 'upcoming' === $bucket ? __( 'Inga planerade driftarbeten.', 'finet-troubleshoot' ) : __( 'Inga tidigare driftstörningar.', 'finet-troubleshoot' ) ) ) . '</p>'; } else { echo '<div class="wpfinet-outages__grid">'; foreach ( $outages as $post ) { $this->card( $post ); } echo '</div>'; } echo '</section>'; }
	private function card( \WP_Post $post ): void { $data = ( new OutageRepository() )->public_data( $post, false ); echo '<article class="wpfinet-outage-card"><p><span class="wpfinet-badge">' . esc_html( 'acute' === $data['type'] ? __( 'Akut', 'finet-troubleshoot' ) : __( 'Planerat', 'finet-troubleshoot' ) ) . '</span> <span class="wpfinet-badge wpfinet-badge--status">' . esc_html( $this->status_label( (string) $data['status'] ) ) . '</span></p><h3><a href="' . esc_url( $data['url'] ) . '">' . esc_html( $data['title'] ) . '</a></h3><p>' . esc_html( $data['summary'] ) . '</p><p class="wpfinet-outage-card__meta">' . esc_html( implode( ' • ', $data['services'] ) ) . '<br>' . esc_html( implode( ', ', $data['providers'] ) ) . '</p><p>' . esc_html( sprintf( __( 'Start: %s', 'finet-troubleshoot' ), $this->format_time( (string) $data['start'] ) ) ) . '</p><a class="wpfinet-outage-card__link" href="' . esc_url( $data['url'] ) . '">' . esc_html__( 'Läs mer', 'finet-troubleshoot' ) . '</a></article>'; }
	public function single_content( string $content ): string { static $rendering = false; if ( $rendering || ! is_singular( self::POST_TYPE ) || ! in_the_loop() || ! is_main_query() ) { return $content; } $post = get_post(); if ( ! $post instanceof \WP_Post || self::POST_TYPE !== $post->post_type ) { return $content; } $rendering = true; $data = ( new OutageRepository() )->public_data( $post, false ); $rendering = false; /* 3.0 (B25): 2.0.1 requested the filtered content here, re-entering this filter forever (HTTP 500 after max_execution_time). */ ob_start(); echo '<section class="wpfinet-outage-detail"><p><span class="wpfinet-badge">' . esc_html( $this->status_label( (string) $data['status'] ) ) . '</span></p><dl><dt>' . esc_html__( 'Start', 'finet-troubleshoot' ) . '</dt><dd>' . esc_html( $this->format_time( (string) $data['start'] ) ) . '</dd><dt>' . esc_html__( 'Beräknad sluttid', 'finet-troubleshoot' ) . '</dt><dd>' . esc_html( $data['estimated_end'] ? $this->format_time( (string) $data['estimated_end'] ) : __( 'Okänd', 'finet-troubleshoot' ) ) . '</dd><dt>' . esc_html__( 'Tjänsteleverantör', 'finet-troubleshoot' ) . '</dt><dd>' . esc_html( implode( ', ', $data['providers'] ) ?: '–' ) . '</dd><dt>' . esc_html__( 'Berör', 'finet-troubleshoot' ) . '</dt><dd>' . esc_html( implode( ', ', $data['services'] ) ?: '–' ) . '</dd><dt>' . esc_html__( 'Område', 'finet-troubleshoot' ) . '</dt><dd>' . esc_html( implode( ', ', $data['areas'] ) ?: '–' ) . ( $data['area_note'] ? '<br>' . esc_html( (string) $data['area_note'] ) : '' ) . '</dd></dl>'; if ( $data['estimated_end'] && strtotime( (string) $data['estimated_end'] ) < current_time( 'timestamp' ) && ! in_array( $data['status'], array( 'resolved', 'cancelled' ), true ) ) { echo '<p class="wpfinet-outage-detail__warning">' . esc_html__( 'Beräknad sluttid har passerat. Se senaste statusuppdatering för aktuell information.', 'finet-troubleshoot' ) . '</p>'; } echo '<h2>' . esc_html__( 'Senaste uppdateringar', 'finet-troubleshoot' ) . '</h2><ol class="wpfinet-timeline">'; foreach ( $data['timeline'] as $item ) { echo '<li><time>' . esc_html( $this->format_time( (string) $item['time'] ) ) . '</time><strong>' . esc_html( $this->status_label( (string) $item['status'] ) ) . '</strong><p>' . esc_html( (string) $item['text'] ) . '</p></li>'; } echo '</ol></section>'; return (string) ob_get_clean() . $content; }
	public function banner(): void { $this->render_banner( false ); } public function banner_fallback(): void { $this->render_banner( true ); }
	private function render_banner( bool $fallback ): void { static $shown = false; if ( $shown || ( $fallback && did_action( 'wp_body_open' ) ) || is_admin() ) { return; } $settings = array_replace_recursive( \FinetTroubleshoot\Activator::default_settings(), (array) get_option( 'finet_ts_settings', array() ) ); if ( empty( $settings['outages']['banner_enabled'] ) ) { return; } $outages = array_filter( ( new OutageRepository() )->find( 'current', array(), 5 ), static fn ( \WP_Post $post ): bool => '1' === get_post_meta( $post->ID, self::META_BANNER, true ) || 'acute' === get_post_meta( $post->ID, self::META_TYPE, true ) ); if ( ! $outages ) { return; } $shown = true; $first = reset( $outages ); $version = md5( implode( ',', array_map( static fn ( \WP_Post $post ): string => $post->ID . ':' . $post->post_modified_gmt, $outages ) ) ); $this->enqueue_assets(); echo '<aside class="wpfinet-banner" role="status" data-wpfinet-banner data-version="' . esc_attr( $version ) . '"><div><strong>⚠ ' . esc_html( $first->post_title ) . '</strong>' . ( count( $outages ) > 1 ? ' <span>' . esc_html( sprintf( __( '+%d ytterligare', 'finet-troubleshoot' ), count( $outages ) - 1 ) ) . '</span>' : '' ) . '</div><a href="' . esc_url( get_permalink( $first ) ) . '">' . esc_html__( 'Läs mer', 'finet-troubleshoot' ) . '</a><button type="button" data-wpfinet-banner-close aria-label="' . esc_attr__( 'Stäng driftmeddelande', 'finet-troubleshoot' ) . '">×</button></aside>'; }
	public function routes(): void { register_rest_route( 'wpfinet/v1', '/outages/current', array( 'methods' => \WP_REST_Server::READABLE, 'callback' => array( $this, 'rest_current' ), 'permission_callback' => '__return_true' ) ); register_rest_route( 'wpfinet/v1', '/outages', array( 'methods' => \WP_REST_Server::READABLE, 'callback' => array( $this, 'rest_outages' ), 'permission_callback' => '__return_true' ) ); }
	public function rest_current( \WP_REST_Request $request ): \WP_REST_Response { return $this->rest_outages( $request, 'current' ); }
	public function rest_outages( \WP_REST_Request $request, string $force = '' ): \WP_REST_Response { $bucket = $force ?: sanitize_key( (string) $request->get_param( 'status' ) ); $bucket = in_array( $bucket, array( 'current', 'upcoming', 'past' ), true ) ? $bucket : 'current'; $filters = array_filter( array( 'service' => sanitize_title( (string) $request->get_param( 'service' ) ), 'provider' => sanitize_title( (string) $request->get_param( 'provider' ) ), 'area' => sanitize_title( (string) $request->get_param( 'area' ) ) ) ); $posts = ( new OutageRepository() )->find( $bucket, $filters, 50 ); return rest_ensure_response( array_map( static fn ( \WP_Post $post ): array => ( new OutageRepository() )->public_data( $post ), $posts ) ); }
	public function flush(): void { ( new OutageRepository() )->flush(); }
	private function enqueue_assets(): void { if ( ! wp_style_is( 'wpfinet-outages', 'registered' ) ) { $this->assets(); } wp_enqueue_style( 'wpfinet-outages' ); wp_enqueue_script( 'wpfinet-outages' ); }
	private function save_time( string $value ): string { if ( ! $value ) { return ''; } $time = \DateTimeImmutable::createFromFormat( 'Y-m-d\\TH:i', $value, wp_timezone() ); return $time ? $time->format( 'Y-m-d H:i:s' ) : ''; }
	private function input_time( string $value ): string { if ( ! $value ) { return ''; } $time = \DateTimeImmutable::createFromFormat( 'Y-m-d H:i:s', $value, wp_timezone() ); return $time ? $time->format( 'Y-m-d\\TH:i' ) : ''; }
	private function format_time( string $value ): string { if ( ! $value ) { return __( 'Okänd', 'finet-troubleshoot' ); } $time = \DateTimeImmutable::createFromFormat( 'Y-m-d H:i:s', $value, wp_timezone() ); return $time ? wp_date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $time->getTimestamp(), wp_timezone() ) : $value; }
}
